// web/Signup.tsx (React)
import { useState } from 'react'

export function Signup({ onSubmit }: { onSubmit: (email: string) => void }) {
  const [email, setEmail] = useState('')
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: 16 }}>
      <b>Create your account</b>
      <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <button disabled={email === ''} onClick={() => onSubmit(email)}>Continue</button>
    </div>
  )
}

// ios/Signup.swift
struct Signup: View {
  let onSubmit: (String) -> Void
  @State private var email = ""
  var body: some View {
    VStack(spacing: 12) {
      Text("Create your account").bold()
      TextField("", text: $email).keyboardType(.emailAddress)
      Button("Continue") { onSubmit(email) }.disabled(email.isEmpty)
    }
    .padding(16)
  }
}

// android/Signup.kt
@Composable
fun Signup(onSubmit: (String) -> Unit) {
  var email by remember { mutableStateOf("") }
  Column(verticalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.padding(16.dp)) {
    Text("Create your account", fontWeight = FontWeight.Bold)
    TextField(
      value = email,
      onValueChange = { email = it },
      keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email),
    )
    Button(onClick = { onSubmit(email) }, enabled = email.isNotEmpty()) { Text("Continue") }
  }
}

