import { signal } from '@pyreon/reactivity'
import { Stack, Field, Select, Button, Text } from '@pyreon/primitives'
import type { SelectOption } from '@pyreon/primitives'

const rooms: SelectOption[] = [
  { value: 'single', label: 'Single room' },
  { value: 'double', label: 'Double room' },
  { value: 'suite', label: 'Suite', disabled: true },
]

export function Booking() {
  const day = signal('')
  const room = signal('')
  return (
    <Stack gap="md" padding={4}>
      <Field kind="date" min="2026-01-01" max="2026-12-31" placeholder="Arrival"
        value={day()} onChangeText={(d) => day.set(d)} />
      <Select value={room()} options={rooms} onChange={(v) => room.set(v)} placeholder="Pick a room" />
      <Button variant="ghost" onPress={() => day.set('')}>Clear</Button>
      <Text>{day() === '' || room() === '' ? 'Pick a day and a room' : `${room()} from ${day()}`}</Text>
    </Stack>
  )
}
